package com.aetherteam.aether.entity.projectile.weapon;

import com.aetherteam.aether.entity.AetherEntityTypes;
import com.aetherteam.aether.network.packet.serverbound.HammerProjectileLaunchPacket;
import net.minecraft.core.particles.ParticleTypes;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.syncher.EntityDataAccessor;
import net.minecraft.network.syncher.EntityDataSerializers;
import net.minecraft.network.syncher.SynchedEntityData;
import net.minecraft.util.Mth;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.projectile.ThrowableProjectile;
import net.minecraft.world.level.Level;
import net.minecraft.world.phys.BlockHitResult;
import net.minecraft.world.phys.EntityHitResult;
import net.minecraft.world.phys.HitResult;
import net.neoforged.neoforge.network.PacketDistributor;

import java.util.List;

public class HammerProjectile extends ThrowableProjectile {
    private static final EntityDataAccessor<Boolean> DATA_JEB_ID = SynchedEntityData.defineId(HammerProjectile.class, EntityDataSerializers.BOOLEAN);

    private int ticksInAir = 0;

    public HammerProjectile(EntityType<? extends HammerProjectile> type, Level level) {
        super(type, level);
    }

    public HammerProjectile(LivingEntity owner, Level level) {
        super(AetherEntityTypes.HAMMER_PROJECTILE.get(), owner, level);
    }

    public HammerProjectile(Level level) {
        super(AetherEntityTypes.HAMMER_PROJECTILE.get(), level);
    }

    @Override
    protected void defineSynchedData(SynchedEntityData.Builder builder) {
        builder.define(DATA_JEB_ID, false);
    }

    @Override
    public void tick() {
        super.tick();
        if (!this.onGround()) {
            ++this.ticksInAir;
        }
        if (this.ticksInAir > 500) {
            if (!this.level().isClientSide()) {
                this.discard();
            }
        }
        if (this.level().isClientSide()) {
            this.level().addParticle(ParticleTypes.CLOUD, this.getX(), this.getY() + 0.2, this.getZ(), 0.0, 0.0, 0.0);
        }
    }

    /**
     * Sets the movement parameters for this projectile when shot.
     *
     * @param rotationPitch The {@link Float} for the rotation pitch.
     * @param rotationYaw   The {@link Float} for the rotation yaw.
     * @param velocity      The {@link Float} velocity of the projectile.
     * @param inaccuracy    The {@link Float} inaccuracy of the projectile.
     */
    public void shoot(float rotationPitch, float rotationYaw, float velocity, float inaccuracy) {
        float x = -Mth.sin(rotationYaw * Mth.DEG_TO_RAD) * Mth.cos(rotationPitch * Mth.DEG_TO_RAD);
        float y = -Mth.sin(rotationPitch * Mth.DEG_TO_RAD);
        float z = Mth.cos(rotationYaw * Mth.DEG_TO_RAD) * Mth.cos(rotationPitch * Mth.DEG_TO_RAD);
        super.shoot(x, y, z, velocity, inaccuracy);
    }

    /**
     * Discards the entity when it hits something.
     *
     * @param result The {@link HitResult} of the projectile.
     */
    @Override
    protected void onHit(HitResult result) {
        super.onHit(result);
        if (!this.level().isClientSide()) {
            this.level().broadcastEntityEvent(this, (byte) 3);
            this.discard();
        }
    }

    /**
     * Launches an entity on hit on the server, and spawns explosion particles on client.
     *
     * @param result The {@link EntityHitResult} of the projectile.
     */
    @Override
    protected void onHitEntity(EntityHitResult result) {
        Entity target = result.getEntity();
        if (!this.level().isClientSide()) {
            this.launchTarget(target);
            this.level().broadcastEntityEvent(this, (byte) 70);
        } else {
            PacketDistributor.sendToServer(new HammerProjectileLaunchPacket(target.getId(), this.getId()));
            this.spawnParticles();
        }
    }

    /**
     * Launches nearby entities in a 5 block radius when hitting a block on the server, and spawns explosion particles on client.
     *
     * @param result The {@link BlockHitResult} of the projectile.
     */
    @Override
    protected void onHitBlock(BlockHitResult result) {
        super.onHitBlock(result);
        List<Entity> list = this.level().getEntities(this, this.getBoundingBox().inflate(5.0));
        for (Entity target : list) {
            if (!this.level().isClientSide()) {
                this.launchTarget(target);
            } else {
                PacketDistributor.sendToServer(new HammerProjectileLaunchPacket(target.getId(), this.getId()));
            }
        }
        if (!this.level().isClientSide()) {
            this.level().broadcastEntityEvent(this, (byte) 70);
        } else {
            this.spawnParticles();
        }
    }

    private void spawnParticles() {
        for (int j = 0; j < 8; j++) {
            this.level().addParticle(ParticleTypes.EXPLOSION, this.getX(), this.getY(), this.getZ(), 0.0, 0.0, 0.0);
            this.level().addParticle(ParticleTypes.EXPLOSION, this.getX(), this.getY(), this.getZ(), 0.0, 0.0, 0.0);
            this.level().addParticle(ParticleTypes.SMOKE, this.getX(), this.getY(), this.getZ(), 0.0, 0.0, 0.0);
            this.level().addParticle(ParticleTypes.LARGE_SMOKE, this.getX(), this.getY(), this.getZ(), 0.0, 0.0, 0.0);
            this.level().addParticle(ParticleTypes.FLAME, this.getX(), this.getY(), this.getZ(), 0.0, 0.0, 0.0);
        }
    }

    /**
     * Hurts and pushes back an entity.
     *
     * @param target The {@link Entity} to affect.
     */
    public void launchTarget(Entity target) {
        if (target != this.getOwner()) {
            if (this.getOwner() == null || target != this.getOwner().getVehicle()) {
                if (target instanceof LivingEntity livingEntity) {
                    livingEntity.hurt(this.damageSources().thrown(this, this.getOwner()), 7);
                    livingEntity.push(this.getDeltaMovement().x(), 0.6, this.getDeltaMovement().z());
                }
            }
        }
    }

    @Override
    protected double getDefaultGravity() {
        return 0.0;
    }

    public void setIsJeb(boolean isJeb) {
        this.getEntityData().set(DATA_JEB_ID, isJeb);
    }

    /**
     * @return Whether the texture for this projectile is of the Hammer of Jeb, as a {@link Boolean}.
     */
    public boolean getIsJeb() {
        return this.getEntityData().get(DATA_JEB_ID);
    }

    @Override
    public void handleEntityEvent(byte id) {
        if (id == 70) {
            this.spawnParticles();
        } else {
            super.handleEntityEvent(id);
        }
    }

    @Override
    public void addAdditionalSaveData(CompoundTag tag) {
        super.addAdditionalSaveData(tag);
        tag.putInt("TicksInAir", this.ticksInAir);
    }

    @Override
    public void readAdditionalSaveData(CompoundTag tag) {
        super.readAdditionalSaveData(tag);
        if (tag.contains("TicksInAir")) {
            this.ticksInAir = tag.getInt("TicksInAir");
        }
    }
}

package wayoftime.bloodmagic.common.tile;

import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.entity.BlockEntityType;
import net.minecraft.world.level.block.state.BlockState;
import wayoftime.bloodmagic.common.alchemyarray.AlchemyArrayEffect;
import wayoftime.bloodmagic.core.registry.AlchemyArrayRegistry;
import wayoftime.bloodmagic.util.Constants;

public class TileAlchemyArray extends TileInventory
{
	public boolean isActive = false;
	public int activeCounter = 0;
	public Direction rotation = Direction.from2DDataValue(0);
	public int rotateCooldown = 0;

	private String key = "";
	public AlchemyArrayEffect arrayEffect;
	private boolean doDropIngredients = true;

	public TileAlchemyArray(BlockEntityType<?> type, BlockPos pos, BlockState state)
	{
		super(type, 2, "alchemyarray", pos, state);
	}

	public TileAlchemyArray(BlockPos pos, BlockState state)
	{
		this(BloodMagicTileEntities.ALCHEMY_ARRAY_TYPE.get(), pos, state);
	}

	public void onEntityCollidedWithBlock(BlockState state, Entity entity)
	{
		if (arrayEffect != null)
		{
			arrayEffect.onEntityCollidedWithBlock(this, getLevel(), worldPosition, state, entity);
		}
	}

	@Override
	public void deserialize(CompoundTag tagCompound)
	{
		super.deserialize(tagCompound);
		this.isActive = tagCompound.getBoolean("isActive");
		this.activeCounter = tagCompound.getInt("activeCounter");
		this.key = tagCompound.getString("stringKey");
		if (!tagCompound.contains("doDropIngredients")) // Check if the array is old
		{
			this.doDropIngredients = true;
		} else
		{
			this.doDropIngredients = tagCompound.getBoolean("doDropIngredients");
		}
		this.rotation = Direction.from2DDataValue(tagCompound.getInt(Constants.NBT.DIRECTION));

		CompoundTag arrayTag = tagCompound.getCompound("arrayTag");
//		arrayEffect = AlchemyArrayRegistry.getEffect(world, this.getStackInSlot(0), this.getStackInSlot(1));
		if (arrayEffect != null)
		{
			arrayEffect.readFromNBT(arrayTag);
		}
	}

	public void doDropIngredients(boolean drop)
	{
		this.doDropIngredients = drop;
	}

	@Override
	public CompoundTag serialize(CompoundTag tagCompound)
	{
		super.serialize(tagCompound);
		tagCompound.putBoolean("isActive", isActive);
		tagCompound.putInt("activeCounter", activeCounter);
		tagCompound.putString("stringKey", "".equals(key) ? "empty" : key.toString());
		tagCompound.putBoolean("doDropIngredients", doDropIngredients);
		tagCompound.putInt(Constants.NBT.DIRECTION, rotation.get2DDataValue());

		CompoundTag arrayTag = new CompoundTag();
		if (arrayEffect != null)
		{
			arrayEffect.writeToNBT(arrayTag);
		}
		tagCompound.put("arrayTag", arrayTag);

		return tagCompound;
	}

	public void tick()
	{
//		System.out.println("Active counter: " + this.activeCounter);
		if (isActive && attemptCraft())
		{
			activeCounter++;
		} else
		{
			isActive = false;
			doDropIngredients = true;
			activeCounter = 0;
			arrayEffect = null;
			key = "empty";
		}
		if (rotateCooldown > 0)
			rotateCooldown--;
	}

	public boolean attemptCraft()
	{
		if (arrayEffect != null)
		{
			isActive = true;

		} else
		{
			AlchemyArrayEffect effect = AlchemyArrayRegistry.getEffect(level, this.getItem(0), this.getItem(1));
			if (effect == null)
			{
//				key = effect.i
				return false;
			} else
			{
				arrayEffect = effect;
			}
		}

		if (arrayEffect != null)
		{
			isActive = true;
			if (arrayEffect.update(this, this.activeCounter))
			{
				this.removeItem(0, 1);
				this.removeItem(1, 1);
				this.getLevel().setBlockAndUpdate(getBlockPos(), Blocks.AIR.defaultBlockState());
				return false;
			}

			return true;
		}
		return false;
	}

//	@Override
	public Direction getRotation()
	{
		return rotation;
	}

	public void setRotation(Direction rotation)
	{
		this.rotation = rotation;
	}

	@Override
	public boolean canPlaceItem(int slot, ItemStack itemstack)
	{
		return slot == 0 || slot == 1;
	}
}

package wayoftime.bloodmagic.common.tile;

import java.util.Locale;

import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.Containers;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.block.entity.BlockEntityType;
import net.minecraft.world.level.block.state.BlockState;
import wayoftime.bloodmagic.api.compat.EnumDemonWillType;
import wayoftime.bloodmagic.common.block.BlockDemonCrystal;
import wayoftime.bloodmagic.common.tile.base.TileTicking;
import wayoftime.bloodmagic.demonaura.WorldDemonWillHandler;
import wayoftime.bloodmagic.util.Constants;
import wayoftime.bloodmagic.will.DemonWillHolder;

public class TileDemonCrystal extends TileTicking
{
	public static final double sameWillConversionRate = 45;
	public static final double defaultWillConversionRate = 90;
	public static final double timeDelayForWrongWill = 0.6;
	public final int maxWill = 100;
	public DemonWillHolder holder = new DemonWillHolder();
	public double progressToNextCrystal = 0;
	public int internalCounter = 0;
	public Direction placement = Direction.UP; // Side that this crystal is placed on.

	public double injectedWill = 0;
	public double speedModifier = 1;
	public double appliedConversionRate = 45;

	public EnumDemonWillType willType;

	public TileDemonCrystal(BlockEntityType<?> type, EnumDemonWillType willType, BlockPos pos, BlockState state)
	{
		super(type, pos, state);
		this.willType = willType;
	}

	public TileDemonCrystal(EnumDemonWillType willType, BlockPos pos, BlockState state)
	{
		this(BloodMagicTileEntities.DEMON_CRYSTAL_TYPE.get(), willType, pos, state);
	}

	public TileDemonCrystal(BlockPos pos, BlockState state)
	{
		this(BloodMagicTileEntities.DEMON_CRYSTAL_TYPE.get(), EnumDemonWillType.DEFAULT, pos, state);
	}

	@Override
	public void onUpdate()
	{
		if (level.isClientSide)
		{
			return;
		}

		internalCounter++;

		if (internalCounter % 20 == 0)
		{
			int crystalCount = getCrystalCount();
			if (crystalCount < 7)
			{
				EnumDemonWillType type = getWillType();

				double value = WorldDemonWillHandler.getCurrentWill(getLevel(), worldPosition, type);

				if (value >= 0.5)
				{
					double nextProgress = getCrystalGrowthPerSecond(value);

					double bufferDrainRate = (sameWillConversionRate - appliedConversionRate);
					double conversionRate = Math.min(appliedConversionRate, sameWillConversionRate);

					if (injectedWill > 0 && bufferDrainRate > 0)
					{
						nextProgress = Math.min(injectedWill / bufferDrainRate, nextProgress);
					}

					nextProgress = Math.min(WorldDemonWillHandler.drainWill(getLevel(), getBlockPos(), type, nextProgress * conversionRate, true) / conversionRate, nextProgress);
					progressToNextCrystal += nextProgress;

					if (injectedWill > 0 && bufferDrainRate > 0)
					{
						injectedWill = Math.max(0, injectedWill - nextProgress * bufferDrainRate);
						if (injectedWill <= 0)
						{
							appliedConversionRate = sameWillConversionRate;
							speedModifier = 1;
						}
					}
				} else if (type != EnumDemonWillType.DEFAULT)
				{
					// Does not use the injectedWill if it's not the same type
					value = WorldDemonWillHandler.getCurrentWill(getLevel(), worldPosition, EnumDemonWillType.DEFAULT);
					if (value > 0.5)
					{
						double nextProgress = getCrystalGrowthPerSecond(value) * timeDelayForWrongWill;
						progressToNextCrystal += WorldDemonWillHandler.drainWill(getLevel(), getBlockPos(), EnumDemonWillType.DEFAULT, nextProgress * defaultWillConversionRate, true) / defaultWillConversionRate;
					}
				}

				if (speedModifier <= 0)
				{
					speedModifier = 1;
				}

				checkAndGrowCrystal();
			}
		}

	}

	public double getInjectedWill()
	{
		return injectedWill;
	}

	public void applyCatalyst(double addedInjectedWill, double speedModifier, double conversionRate)
	{
		if (this.speedModifier < speedModifier)
		{
			this.speedModifier = speedModifier;
		}

		if (this.appliedConversionRate > conversionRate)
		{
			this.appliedConversionRate = conversionRate;
		}

		injectedWill += addedInjectedWill;
	}

	/**
	 * Encourages the crystal to grow by a large percentage by telling it to drain
	 * will from the aura.
	 *
	 * @param willDrain          The amount of drain that is needed for the crystal
	 *                           to grow successfully for the desired amount. Can be
	 *                           more than the base amount.
	 * @param progressPercentage
	 * @return percentage actually grown.
	 */
	public double growCrystalWithWillAmount(double willDrain, double progressPercentage)
	{
		int crystalCount = getCrystalCount();
		if (crystalCount >= 7)
		{
			return 0;
		}

		EnumDemonWillType type = this.getWillType();

		double value = WorldDemonWillHandler.getCurrentWill(getLevel(), worldPosition, type);
		double percentDrain = willDrain <= 0 ? 1 : Math.min(1, value / willDrain);
		if (percentDrain <= 0)
		{
			return 0;
		}

		// Verification that you can actually drain the will from this chunk, for future
		// proofing.
		WorldDemonWillHandler.drainWill(getLevel(), worldPosition, type, percentDrain * willDrain, true);
		progressToNextCrystal += percentDrain * progressPercentage;

		checkAndGrowCrystal();

		return percentDrain * progressPercentage;
	}

	public EnumDemonWillType getWillType()
	{
		return willType;
	}

	public void checkAndGrowCrystal()
	{
		int crystalCount = getCrystalCount();
		if (progressToNextCrystal >= 1 && internalCounter % 100 == 0 && crystalCount < 7)
		{
			progressToNextCrystal--;
			this.setCrystalCount(crystalCount + 1);
			setChanged();
			notifyUpdate();
		}
	}

	public double getMaxWillForCrystal()
	{
		return 50;
	}

	public boolean dropSingleCrystal()
	{
		int crystalCount = getCrystalCount();
		if (!getLevel().isClientSide && crystalCount > 1)
		{
			EnumDemonWillType type = getWillType();
//			EnumDemonWillType type = state.getValue(BlockDemonCrystal.TYPE);
			ItemStack stack = BlockDemonCrystal.getItemStackDropped(type, 1);
			if (!stack.isEmpty())
			{
				setCrystalCount(crystalCount - 1);
				Containers.dropItemStack(getLevel(), worldPosition.getX(), worldPosition.getY(), worldPosition.getZ(), stack);
				notifyUpdate();
				setChanged();
				return true;
			}
		}

		return false;
	}

	public double getCrystalGrowthPerSecond(double will)
	{
		double speed = 1.0 / 200 * Math.sqrt(will / 200);
		if (speedModifier > 0)
		{
			speed *= speedModifier;
		}

		return speed;
	}

	@Override
	public void deserialize(CompoundTag tag)
	{
		holder.readFromNBT(tag, "Will");
		placement = Direction.from3DDataValue(tag.getInt("placement"));
		progressToNextCrystal = tag.getDouble("progress");

		if (!tag.contains(Constants.NBT.WILL_TYPE))
		{
			this.willType = EnumDemonWillType.DEFAULT;
		} else
		{
			this.willType = EnumDemonWillType.valueOf(tag.getString(Constants.NBT.WILL_TYPE).toUpperCase(Locale.ROOT));
		}

		injectedWill = tag.getDouble(Constants.NBT.INJECTED_WILL);
		speedModifier = tag.getDouble(Constants.NBT.SPEED_MODIFIER);
		appliedConversionRate = tag.getDouble(Constants.NBT.APPLIED_RATE);
	}

	@Override
	public CompoundTag serialize(CompoundTag tag)
	{
		holder.writeToNBT(tag, "Will");
		tag.putInt("placement", placement.get3DDataValue());
		tag.putDouble("progress", progressToNextCrystal);

		if (willType == EnumDemonWillType.DEFAULT)
		{
			if (tag.contains(Constants.NBT.WILL_TYPE))
			{
				tag.remove(Constants.NBT.WILL_TYPE);
			}

		} else
		{
			tag.putString(Constants.NBT.WILL_TYPE, willType.toString());
		}

		tag.putDouble(Constants.NBT.INJECTED_WILL, injectedWill);
		tag.putDouble(Constants.NBT.SPEED_MODIFIER, speedModifier);
		tag.putDouble(Constants.NBT.APPLIED_RATE, appliedConversionRate);

		return tag;
	}

	public int getCrystalCount()
	{
		BlockState state = level.getBlockState(getBlockPos());
		return state.getValue(BlockDemonCrystal.AGE) + 1;
	}

	public void setCrystalCount(int crystalCount)
	{
		BlockState state = level.getBlockState(getBlockPos());
		level.setBlockAndUpdate(getBlockPos(), state.setValue(BlockDemonCrystal.AGE, crystalCount - 1));
	}

	public Direction getPlacement()
	{
		return placement;
	}

	public void setPlacement(Direction placement)
	{
		this.placement = placement;
	}

//	@Override
//	protected void onDataPacketClientReceived()
//	{
//		super.onDataPacketClientReceived();
//		notifyUpdate();
//	}
}

package wayoftime.bloodmagic.common.tile;

import java.util.List;

import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.resources.ResourceLocation;
